  v == 1
    ? "https://www.awslmh.net"
    : v == 2
    ? "https://www.abamhc1.click"
    : v == 3
    ? "https://abamh.com"
    : "https://www.awslmh.net"
headers = `{
  "v": ${v};
  "Host": ${host}
}`
source.putLoginHeader(headers);
function ti(text, i, z) {
  reg = new RegExp(i, "g");
  return text.replace(reg, z);
}
